   bn: "কুইজম কাঠামোতে, প্রতিফলিত বর্ণমালা ১৮টি মূল অক্ষর দ্বারা গঠিত একটি গভীর প্রতীকী কাঠামো হিসেবে কাজ করে: A, B, C, D, E, F, G, H, I ক্রমটি Z, Q, P, O, N, M, L, K, J দ্বারা প্রতিবিম্বিত হয়। গাণিতিকভাবে, 9 + 9 = 18 হ্রাস পেয়ে 9 (1 + 8 = 9) হয়, যা পরম শক্তি (1) এবং শূন্যতার প্রতিফলন (8) এর সংযোগকে প্রতিনিধিত্ব করে;",

