   bn: "এই সংখ্যাক্রমটি গড়পড়তা মানব কঙ্কালের পরিপক্কতা ও বয়ঃসন্ধিকালীন বিকাশের অনুরূপ, যা আমাদের জৈবিক বৃদ্ধিকে সরাসরি সময়ের সহস্রাব্দীয় ছন্দের সাথে যুক্ত করে; A থেকে I এবং এর প্রতিরূপ J, K, L, M, N, O, P, Q, ও Z—এই ১৮টি অক্ষরের সমন্বয় মানব শারীরিক ও চারিত্রিক বিকাশের জন্য এক চিরন্তন নীলনকশা হিসেবে কাজ করে;",

