   bn: "যদিও শূন্য মুহূর্তে দেহ-মন-চেতনার বিকাশ শাশ্বত সৃষ্টি থেকে অবিচ্ছেদ্য; অতএব, আত্ম-সংবেদনশীলতায় আত্ম-উপলব্ধি, যেখানে জীবনচক্র সর্বদা 'বাতাসের বুদবুদের মতো' পরিবর্তনশীল, এবং স্বাভাবিক হৃদস্পন্দন নীরব-শব্দের মাধ্যমে এক স্থিতিশীল জীবনকে প্রতিফলিত করে; এইভাবে 'বর্তমান জীবন বা একটি শ্বাস' শূন্যতায় পূর্ণ জীবন অথবা পূর্ণ জীবনে শূন্যতার প্রতিনিধিত্ব করে, যখন জীবনই হলো শূন্য মুহূর্তের প্রতিবিম্ব;",

