   bn: "आखिरकार, टाइम और स्पेस एक बैटरी की एनर्जी की स्टेबिलिटी के साथ एक-दूसरे के पीछे चलते हैं, जो सोलर सिस्टम में पाए जाने वाले बैलेंस को दिखाता है, जहाँ इंसान का रूप आसमानी दुनिया के एक छोटे रूप के तौर पर काम करता है; इस सटीक तालमेल से, इंसानी सफ़र अपना साइकिल पूरा करता है, और यूनिवर्सल सोर्स के गहरे रिफ्लेक्शन के तौर पर वापस अपने असली रूप में 'लैंडिंग' करता है;",

   hi: "आखिरकार, टाइम और स्पेस एक बैटरी की एनर्जी की स्टेबिलिटी के साथ एक-दूसरे के पीछे चलते हैं, जो सोलर सिस्टम में पाए जाने वाले बैलेंस को दिखाता है, जहाँ इंसान का रूप आसमानी दुनिया के एक छोटे रूप के तौर पर काम करता है; इस सटीक तालमेल से, इंसानी सफ़र अपना साइकिल पूरा करता है, और यूनिवर्सल सोर्स के गहरे रिफ्लेक्शन के तौर पर वापस अपने असली रूप में 'लैंडिंग' करता है;",

   sa: "अन्ततः कालः अन्तरिक्षं च बैटरी ऊर्जायाः स्थिरतायाः सह परस्परं अनुसरणं कुर्वन्ति, सौरमण्डलस्य अन्तः दृश्यमानस्य समतोलस्य प्रतिबिम्बं कुर्वन्ति यत्र मानवरूपं आकाशीयसमग्रस्य सूक्ष्मविश्वरूपेण कार्यं करोति एतस्य सटीकसमन्वयस्य माध्यमेन मानवयात्रा स्वचक्रं सम्पन्नं करोति, सार्वभौमिकस्रोतस्य गहनप्रतिबिम्बरूपेण पुनः निरपेक्षात्मनि 'अवरोहति';",
