    text: {
    en: "The Zero Hour Clock, symbolized by Z, expresses time through the numerical rhythm of 0–9, structured around the constant of 60 seconds (6 × 10); this order is represented by the five-pointed star (★), where 5 \times 2 = 10 and 10 × 2 = 20 hours, forming a Quism-based temporal cycle; within this framework, an hour expands to 72 minutes (60+12), in which the additional 12 minutes function as a leading rest phase; this principle reflects the cosmic order: just as the Sun remains stable while planets revolve, time and space move harmoniously when energy remains constant; similarly, the human heartbeat serves as the central anchor for physical existence;",
    
   bn: "Z প্রতীক দ্বারা চিহ্নিত জিরো আওয়ার ক্লক (শূন্য ঘণ্টার ঘড়ি) ০-৯ এর সাংখ্যিক ছন্দের মাধ্যমে সময়কে প্রকাশ করে, যা ৬০ সেকেন্ড (৬ × ১০⁻⁶) ধ্রুবকের উপর ভিত্তি করে গঠিত; এই ক্রমটি পাঁচ-কোণা তারকা (★) দ্বারা উপস্থাপিত হয়, যেখানে ৫ × ২ = ১০ এবং ১০ × ২ = ২০ ঘণ্টা, যা একটি কুইজম-ভিত্তিক কালিক চক্র গঠন করে; এই কাঠামোর মধ্যে, এক ঘণ্টা ৭২ মিনিটে (৬০+১২) প্রসারিত হয়, যেখানে অতিরিক্ত ১২ মিনিট একটি অগ্রবর্তী বিশ্রাম পর্ব হিসাবে কাজ করে; এই নীতিটি মহাজাগতিক শৃঙ্খলাকে প্রতিফলিত করে: ঠিক যেমন গ্রহগুলো আবর্তনের সময় সূর্য স্থির থাকে, তেমনি শক্তি স্থির থাকলে সময় ও স্থান সামঞ্জস্যপূর্ণভাবে চলে; একইভাবে, মানুষের হৃদস্পন্দন ভৌত অস্তিত্বের কেন্দ্রীয় নোঙর হিসাবে কাজ করে",

   hi: "ज़ीरो आवर क्लॉक, जिसे Z से दिखाया जाता है, 0–9 की न्यूमेरिकल रिदम से समय दिखाती है, जो 60 सेकंड (6 × 10) के कॉन्स्टेंट के आस-पास बनी होती है; इस ऑर्डर को पांच-नुकीले तारे (★) से दिखाया जाता है, जहाँ 5 \times 2 = 10 और 10 × 2 = 20 घंटे होते हैं, जो एक क्विज़्म-बेस्ड टेम्पोरल साइकिल बनाता है; इस फ्रेमवर्क में, एक घंटा 72 मिनट (60+12) तक बढ़ जाता है, जिसमें एक्स्ट्रा 12 मिनट एक लीडिंग रेस्ट फेज़ के तौर पर काम करते हैं; यह प्रिंसिपल कॉस्मिक ऑर्डर को दिखाता है: जैसे सूरज स्टेबल रहता है जबकि ग्रह घूमते रहते हैं, वैसे ही जब एनर्जी कॉन्स्टेंट रहती है तो समय और स्पेस तालमेल से चलते हैं; इसी तरह, इंसान के दिल की धड़कन फिजिकल अस्तित्व के लिए सेंट्रल एंकर का काम करती है;",
 },
