     text: {
    en: "The alphabet from A–Z represents the origin of thought and creation, much like the sun as a single point reflecting the entire solar system; just as the Moon's orbital path and the rhythms of tides maintain the balance of nature, the vital force remains fixed within human consciousness as a central anchor; the layers of the mind and the world of dreams act as mirrors to this mysterious universe, eventually manifesting in the formation of the physical body during pregnancy;",
    
   bn: "A থেকে Z পর্যন্ত বর্ণমালা চিন্তা ও সৃষ্টির উৎসের প্রতিনিধিত্ব করে, অনেকটা সূর্যের মতো যা একটি একক বিন্দু হিসেবে সমগ্র সৌরজগতকে প্রতিফলিত করে; ঠিক যেমন চাঁদের কক্ষপথ এবং জোয়ার-ভাটার ছন্দ প্রকৃতির ভারসাম্য বজায় রাখে, তেমনি প্রাণশক্তি মানব চেতনার মধ্যে একটি কেন্দ্রীয় নোঙর হিসেবে স্থির থাকে; মনের স্তরসমূহ এবং স্বপ্নের জগৎ এই রহস্যময় মহাবিশ্বের দর্পণ হিসেবে কাজ করে, যা অবশেষে গর্ভাবস্থায় শারীরিক দেহ গঠনের মাধ্যমে প্রকাশিত হয়;",

   hi: "A-Z तक के अक्षर विचार और रचना की शुरुआत को दिखाते हैं, ठीक वैसे ही जैसे सूरज एक बिंदु के तौर पर पूरे सोलर सिस्टम को दिखाता है; जैसे चांद का चक्कर और लहरों की लय प्रकृति का बैलेंस बनाए रखते हैं, वैसे ही जीवन शक्ति इंसानी चेतना में एक सेंट्रल सहारे की तरह स्थिर रहती है; मन की परतें और सपनों की दुनिया इस रहस्यमयी दुनिया के आईने की तरह काम करती हैं, जो आखिर में प्रेग्नेंसी के दौरान शरीर बनने में दिखाई देती हैं;",

   sa: "A–Z इत्यस्मात् वर्णमाला विचारस्य सृष्टेः च उत्पत्तिं प्रतिनिधियति, यथा सूर्यः सम्पूर्णं सौरमण्डलं प्रतिबिम्बयति एकबिन्दुरूपेण; यथा चन्द्रस्य कक्षामार्गः, ज्वार-भाटा-तालः च प्रकृतेः सन्तुलनं निर्वाहयन्ति, तथैव प्राणशक्तिः मानव-चेतनायाः अन्तः केन्द्र-लंगररूपेण नियतं तिष्ठति मनसः स्वप्नलोकस्य च स्तराः अस्य रहस्यमयस्य जगतः दर्पणरूपेण कार्यं कुर्वन्ति, अन्ते गर्भावस्थायां भौतिकशरीरस्य निर्माणे प्रकटिताः भवन्ति",
 },
